#include <netinet/in.h>

namespace blockchain {

struct Address {
    uint8_t bytes[20];
    bool operator==(const Address& o) const { return memcmp(bytes, o.bytes, 20) == 0; }
    bool operator<(const Address& o) const { return memcmp(bytes, o.bytes, 20) < 0; }
};

enum class Role : uint8_t { NONE = 0, ORACLE = 1, ADMIN = 2, OWNER = 3 };

struct OracleEndpoint {
    std::string hostname;
    uint16_t port;
    uint64_t registered_at;
    uint32_t resolved_ip;  // cached resolved IP
    uint64_t last_resolved;
};

class AccessControlledOracle {
private:
    Address owner_;
    std::map<Address, Role> roles_;
    std::map<std::string, OracleEndpoint> endpoints_;
    std::map<std::string, std::string> cached_responses_;
    uint64_t dns_cache_ttl_;
    uint64_t request_window_;
    std::mutex state_mutex_;

    uint64_t current_time() const {
        return std::chrono::duration_cast<std::chrono::seconds>(
            std::chrono::system_clock::now().time_since_epoch()).count();
    }

    // Reject values that could enable HTTP header/request injection (CWE-113).
    static bool is_safe_http_field(const std::string& s) {
        for (unsigned char c : s) {
            if (c == '\r' || c == '\n' || c < 0x20 || c == 0x7f) return false;
        }
        return true;
    }

    uint32_t resolve_hostname(const std::string& hostname) {
        // Simulated DNS resolution - in production calls system resolver
        // Returns packed IPv4 address
        struct addrinfo hints = {}, *result = nullptr;
        hints.ai_family = AF_INET;
        hints.ai_socktype = SOCK_STREAM;
        if (getaddrinfo(hostname.c_str(), nullptr, &hints, &result) != 0)
            return 0;
        uint32_t ip = ((struct sockaddr_in*)result->ai_addr)->sin_addr.s_addr;
        freeaddrinfo(result);
        return ip;
    }

    bool is_internal_ip(uint32_t ip) const {
        uint8_t first = ip & 0xFF;
        uint8_t second = (ip >> 8) & 0xFF;
        // Block RFC1918 ranges
        if (first == 10) return true;
        if (first == 172 && (second >= 16 && second <= 31)) return true;
        if (first == 192 && second == 168) return true;
        if (first == 127) return true;
        if (ip == 0) return true;
        return false;
    }

    bool validate_endpoint_security(OracleEndpoint& ep) {
        uint64_t now = current_time();
        // Re-resolve if cache expired
        if (now - ep.last_resolved > dns_cache_ttl_) {
            ep.resolved_ip = resolve_hostname(ep.hostname);
            ep.last_resolved = now;
        }
        return !is_internal_ip(ep.resolved_ip);
    }

    std::string fetch_oracle_data(OracleEndpoint& ep, const std::string& query) {
        // Reject queries that could inject HTTP headers/requests (CWE-113)
        if (!is_safe_http_field(query) || !is_safe_http_field(ep.hostname)) {
            return "ERROR: invalid request field";
        }

        // Validate the endpoint resolves to a safe IP
        if (!validate_endpoint_security(ep)) {
            return "ERROR: endpoint resolves to internal IP";
        }

        // SECURE: Use the same validated/cached IP for the actual connection
        // No second resolution - connect using the IP we already validated
        uint32_t connect_ip = ep.resolved_ip;

        // Verify again right before connection (defense in depth)
        if (is_internal_ip(connect_ip)) {
            return "ERROR: endpoint resolves to internal IP";
        }

        // Connect using the validated cached IP
        std::ostringstream request;
        request << "GET /oracle?q=" << query << " HTTP/1.1\r\n";
        request << "Host: " << ep.hostname << "\r\n\r\n";

        // Connection uses connect_ip which was validated above
        return simulate_http_request(connect_ip, ep.port, request.str());
    }

    std::string simulate_http_request(uint32_t ip, uint16_t port, const std::string& req) {
        // In production: opens socket to ip:port, sends req, returns response
        return "SIMULATED_RESPONSE";
    }

public:
    AccessControlledOracle(Address owner, uint64_t cache_ttl = 300)
        : owner_(owner), dns_cache_ttl_(cache_ttl), request_window_(60) {
        roles_[owner] = Role::OWNER;
    }

    bool grant_role(const Address& caller, const Address& target, Role role) {
        std::lock_guard<std::mutex> lock(state_mutex_);
        if (roles_[caller] < Role::ADMIN) return false;
        if (role >= roles_[caller]) return false;
        roles_[target] = role;
        return true;
    }

    bool register_endpoint(const Address& caller, const std::string& name,
                          const std::string& hostname, uint16_t port) {
        std::lock_guard<std::mutex> lock(state_mutex_);
        if (roles_[caller] < Role::ORACLE) return false;

        // Reject hostnames that could inject HTTP headers (CWE-113)
        if (!is_safe_http_field(hostname)) return false;

        OracleEndpoint ep;
        ep.hostname = hostname;
        ep.port = port;
        ep.registered_at = current_time();
        ep.resolved_ip = resolve_hostname(hostname);
        ep.last_resolved = current_time();

        // Initial registration check
        if (is_internal_ip(ep.resolved_ip)) return false;

        endpoints_[name] = ep;
        return true;
    }

    std::string query_oracle(const Address& caller, const std::string& endpoint_name,
                            const std::string& query) {
        std::lock_guard<std::mutex> lock(state_mutex_);
        if (roles_[caller] < Role::ORACLE) return "ERROR: unauthorized";
        if (endpoints_.find(endpoint_name) == endpoints_.end())
            return "ERROR: endpoint not found";

        OracleEndpoint& ep = endpoints_[endpoint_name];
        return fetch_oracle_data(ep, query);
    }

    Role get_role(const Address& addr) const {
        auto it = roles_.find(addr);
        return it != roles_.end() ? it->second : Role::NONE;
    }
};

} // namespace blockchain
